mr-boxington = "1.5.0"
# Pinned rather than "latest" because tak is the measuring instrument: an
# upgrade that changes how it samples would land in the series as a step change
# in mise's numbers, indistinguishable from a real regression. Bump
# deliberately, on a commit that does nothing else.
"github:jdx/tak" = "0.0.9"
age = "latest"
aube = "latest"
bun = "latest"
cargo-binstall = "latest"
communique = "latest"
cargo-insta = "latest"
git-cliff = "latest"
gh = "latest"
hk = "latest"
jq = "latest"
lua-language-server = "latest"
stylua = "latest"
"npm:markdownlint-cli" = "latest"
prettier = "3.9.6"
"npm:ajv-cli" = "latest"
pkl = "latest"
shellcheck = "latest"
shfmt = "latest"
taplo = "latest"
usage = "6.6.1"
wait-for-gh-rate-limit = "latest"
sops = "latest"
node = "24"

[wrappers.cargo]
command = "mbx"
env = { MBX_CARGO_SHIM_MODE = "1" }

[task_config]
includes = ["tasks.toml", "xtasks"]

# Instruction-counted benchmarks (see tak.toml). Needs valgrind for the counts;
# without it tak reports wall clock only and says so, so this still works on
# macOS where there is no usable cachegrind.
#
# `--release`, not `--profile serious`: LTO roughly triples the build for a
# number whose absolute value does not matter. What matters is that every
# measurement in a series is built the same way, and the series is partitioned
# on runner class so a change of build profile would start a fresh one anyway.
[tasks.perf]
dir = "{{config_root}}"
# MISE_OFFLINE keeps `ls`, `env` and `hook-env` off the network. Without it they
# log HTTP warnings and their instruction counts move with whatever the registry
# happened to answer. Ignoring the repository config keeps its development tools
# out of the fixture so editing this file does not change a benchmark's input.
env = { MISE_OFFLINE = "1", MISE_IGNORED_CONFIG_PATHS = "{{config_root}}/mise.toml" }
run = ["mbx build --release", "tak run"]

# Same measurement, appended to refs/notes/tak for this commit. Run by the
# `perf` workflow on every push to main; the notes are the history. Safe to run
# locally — nothing leaves the machine until `tak push`.
[tasks."perf:record"]
dir = "{{config_root}}"
env = { MISE_OFFLINE = "1", MISE_IGNORED_CONFIG_PATHS = "{{config_root}}/mise.toml" }
run = ["mbx build --release", "tak run --record"]

# End-to-end task artifact cache phases. The harness generates an isolated
# large fixture so benchmark inputs never need to be checked into the repo.
[tasks."perf:task-cache"]
dir = "{{config_root}}"
run = ["cargo build --release", "bash benchmarks/task-cache/benchmark.sh"]
amends "package://github.com/jdx/hk/releases/download/v1.55.0/hk@1.55.0#/Config.pkl"
import "package://github.com/jdx/hk/releases/download/v1.55.0/hk@1.55.0#/Builtins.pkl"

local bash_glob = List("*.sh", "xtasks/**", "scripts/**", "e2e/**")
local bash_exclude = List("*.ps1", "**/*.fish", "*.ts", "*.js", "*.json", "*.bat", "**/.*", "src/assets/bash_zsh_support/**", "e2e/shell/xonsh_script", "tmp/install.sh", "**/*.py", "**/*.xsh")
local linters = new Mapping<String, Step> {
    ["schema"] {
        glob = List("schema/**/*.json")
        stdin = "{{ files_list | join(sep='\u{0}') }}"
        check = new CommandSpec {
          command = "xargs -0 -I {} ajv compile -s {} --spec=draft2020 --strict-types=true --strict-tuples=true"
          effect = "read"
        }
        check_first = false
    }
    // uses builtin prettier linter config; run via `mise x` so hk picks up
    // the mise-pinned prettier rather than whatever happens to be on
    // PATH (e.g. a Homebrew prettier), keeping local and CI in sync.
    ["prettier"] = (Builtins.prettier) {
      batch = false
      exclude = "vendor/aqua-registry/**"
      check = new CommandSpec {
        command = "mise x prettier -- prettier --check {{ files }}"
        effect = "read"
      }
      check_list_files = new CommandSpec {
        command = "mise x prettier -- prettier --list-different {{ files }}"
        effect = "read"
      }
      fix = new CommandSpec {
        command = "mise x prettier -- prettier --write {{ files }}"
        effect = "write"
      }
      depends = List("schema")
    }
    //["clippy"] = (Builtins.cargo_clippy) {
    //  check = "cargo clippy --manifest-path {{workspace_indicator}} --all-features -- -Dwarnings"
    //  fix = "cargo clippy --manifest-path {{workspace_indicator}} --all-features --fix --allow-dirty --allow-staged -- -Dwarnings"
    //}
    ["cargo-fmt"] {
      glob = List("**/*.rs")
      check = new CommandSpec {
        command = "cargo fmt --all -- --check"
        effect = "read"
      }
      fix = new CommandSpec {
        command = "cargo fmt --all"
        effect = "write"
      }
    }
    ["cargo-check"] = (Builtins.cargo_check) {
      check = new CommandSpec {
        command = "cargo check --all-features"
        effect = "write"
      }
    }
    ["shellcheck"] = (Builtins.shellcheck) {
      match_any = null
      glob = bash_glob
      exclude = bash_exclude
      batch = true
      check = new CommandSpec {
        command = "shellcheck -x {{ files }}"
        effect = "read"
      }
    }
    ["shfmt"] = (Builtins.shfmt) {
      match_any = null
      check_list_files = new CommandSpec {
        command = """
files=$(shfmt -l -s {{ files }})
if [ -n "$files" ]; then
  echo "$files"
  exit 1
fi
"""
        effect = "read"
      }
      fix = new CommandSpec {
        command = "shfmt -w -s {{ files }}"
        effect = "write"
      }
      glob = bash_glob
      exclude = bash_exclude
    }

    // uses custom pkl linter config
    ["pkl"] {
        glob = "**/*.pkl"
        check = new CommandSpec {
          command = "pkl eval {{files}} >/dev/null"
          effect = "write"
        }
    }

    // uses taplo for TOML formatting and validation
    ["taplo"] {
        glob = List("**/*.toml")
        check = new CommandSpec {
          command = "taplo fmt --check {{files}} && taplo check {{files}}"
          effect = "read"
        }
        fix = new CommandSpec {
          command = "taplo fmt {{files}} && taplo check {{files}}"
          effect = "write"
        }
    }

    // uses lua-language-server to check vfox test plugin Lua files
    // excludes embedded-plugins/ which are vendored from external repos
    ["lua-check"] {
        glob = List("crates/vfox/plugins/**/*.lua")
        check = new CommandSpec {
          command = "lua-language-server --check crates/vfox/plugins/"
          effect = "write"
        }
    }
    ["stylua"] {
        glob = List("crates/vfox/plugins/**/*.lua")
        check = new CommandSpec {
          command = "stylua --check crates/vfox/plugins/"
          effect = "read"
        }
        fix = new CommandSpec {
          command = "stylua crates/vfox/plugins/"
          effect = "write"
        }
    }
    ["actionlint"] {
        glob = List(".github/workflows/*.yml")
        check = new CommandSpec {
          command = "SHELLCHECK_OPTS='--exclude=SC1090 --exclude=SC2046 --exclude=SC2086 --exclude=SC2129' actionlint"
          effect = "read"
        }
    }
    ["markdownlint"] {
        glob = List("**/*.md")
        check = new CommandSpec {
          command = "markdownlint {{ files }}"
          effect = "read"
        }
        fix = new CommandSpec {
          command = "markdownlint --fix {{ files }}"
          effect = "write"
        }
    }
}

hooks {
    ["fix"] {
        fix = true
        steps = linters
    }
    ["check"] {
        steps = linters
    }
}
