/* ─── Hero ─── */
/* .heading wraps .name; hide it too or it occupies an empty grid row */
.VPHero .heading,
.VPHero .name,
.VPHero .tagline,
.VPHero .actions {
  display: none !important;
}

/* VitePress pulls the hero up under the nav with a negative margin
   (nav height + layout-top banner), so padding-top must include that
   offset or the hero content hides behind the navbar. */
.VPHero {
  position: relative;
  z-index: 1;
  padding-top: calc(
    var(--vp-nav-height) + var(--vp-layout-top-height, 0px) + 72px
  ) !important;
  padding-bottom: 56px !important;
}

.VPHero .container {
  max-width: 1120px !important;
  margin: 0 auto !important;
}

.VPHero .main {
  display: block !important;
}

.VPHero .text {
  max-width: none !important;
}

.VPContent.is-home,
.VPHome {
  overflow-x: hidden;
}

.hero-copy {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 860px;
  margin: 0 auto;
  text-align: center;
}

/* Big brand lockup — same composition as the navbar brand, scaled up.
   The navbar copy stays hidden until this scrolls past (see .hide-nav-brand). */
.hero-lockup {
  display: flex;
  align-items: center;
  gap: 16px;
}

.hero-lockup .chef-logo {
  width: auto;
  height: clamp(56px, 8vw, 80px);
}

.lockup-word {
  font-family: "Roc Grotesk", sans-serif;
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  font-weight: 400;
  letter-spacing: -0.02em;
  color: var(--vp-c-text-1);
  white-space: nowrap;
}

.hero-lockup .chef-logo-dark {
  display: none;
}

.dark .hero-lockup .chef-logo-light {
  display: none;
}

.dark .hero-lockup .chef-logo-dark {
  display: inline;
}

.hero-copy h1 {
  margin: 36px 0 0;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: clamp(2.9rem, 6.2vw, 5rem);
  font-weight: 300;
  font-style: normal;
  line-height: 1;
  letter-spacing: -0.01em;
  color: var(--vp-c-text-1);
  text-wrap: balance;
}

.hero-copy h1 em {
  font-style: italic;
  color: var(--vp-c-brand-1);
}

.hero-lede {
  max-width: 58ch;
  margin: 26px 0 0;
  font-size: 1.15rem;
  line-height: 1.6;
  color: var(--vp-c-text-2);
  text-wrap: pretty;
}

.hero-lede code {
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--vp-c-bg-soft);
  color: var(--vp-c-text-1);
  font-family: var(--vp-font-family-mono);
  font-size: 0.88em;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-top: 34px;
}

.action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 48px;
  padding: 0 22px;
  border-radius: 8px;
  font-family: "Roc Grotesk", sans-serif;
  font-size: 0.78rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-decoration: none;
  line-height: 1;
  transition:
    background-color 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease;
}

.action-btn-brand {
  background: var(--vp-c-brand-1);
  color: #fff;
}

.action-btn-brand:hover {
  background: var(--vp-c-brand-2);
}

.action-btn-alt {
  border: 1px solid var(--vp-c-divider);
