}

.action-btn-alt:hover {
  border-color: var(--vp-c-brand-1);
  color: var(--vp-c-brand-1);
}

.hero-meta {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  margin: 26px 0 0;
  font-family: var(--vp-font-family-mono);
  font-size: 0.68rem;
