  text-transform: uppercase;
  color: var(--vp-c-text-3);
}

.hero-meta span + span::before {
  content: "·";
  margin: 0 12px;
}

/* ─── Page frame ─── */
.VPHome .vp-doc {
  max-width: none;
  padding: 0 24px;
}

.landing-page {
  max-width: 1120px;
  margin: 0 auto;
}

/* vp-doc list/link/heading defaults don't fit a composed page */
.landing-page ul,
.landing-page ol {
  margin: 0;
  padding: 0;
  list-style: none;
}

.landing-page li + li {
  margin-top: 0;
}

.landing-page h2,
.landing-page h3 {
  margin: 0;
  padding: 0;
  border: 0;
}

.landing-page a::after {
  content: none !important;
}

.landing-page p a {
  color: var(--vp-c-brand-1);
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--vp-c-brand-1) 40%, transparent);
  text-underline-offset: 3px;
}

.landing-page p a:hover {
  text-decoration-color: var(--vp-c-brand-1);
}

/* ─── Terminal transcript (shared) ─── */
.terminal-lines {
  font-family: var(--vp-font-family-mono);
  font-size: 0.84rem;
  line-height: 1.8;
  color: var(--vp-c-text-1);
  white-space: nowrap;
  overflow: auto;
}

.terminal-lines .prompt {
  color: var(--vp-c-brand-1);
}

.terminal-lines .ok {
  color: var(--vp-c-success-1);
}

.terminal-lines .key {
  color: var(--vp-c-warning-1);
}

.terminal-lines .dim {
  color: var(--vp-c-text-3);
}

/* ─── The card: mise.toml → three outputs ─── */
.hero-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid var(--vp-c-divider);
  border-radius: 10px;
  background: var(--vp-c-bg-soft);
