}

.landing-page .ledger-after li {
  color: var(--vp-c-text-1);
}

.ledger-after li strong {
  font-weight: 500;
}

.ledger-pillars {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 16px;
}

.ledger-pillars span {
  padding: 3px 9px;
  border: 1px solid color-mix(in srgb, var(--pillar) 45%, transparent);
  border-radius: 999px;
  font-family: var(--vp-font-family-mono);
  font-size: 0.64rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--pillar);
}

/* 02 · Stations: three ruled columns */
.stations-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0 32px;
  margin-top: 40px;
}

.station {
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding-top: 20px;
  border-top: 2px solid var(--pillar);
  color: var(--vp-c-text-1);
  text-decoration: none !important;
}

.landing-page .station-cmd {
  margin: 0;
  font-family: var(--vp-font-family-mono);
  font-size: 0.74rem;
  line-height: 1.4;
  color: var(--pillar);
}

.landing-page .station h3 {
  margin: 12px 0 8px;
  font-size: 1.9rem;
  line-height: 1.1;
  color: var(--vp-c-text-1);
  transition: color 0.2s ease;
}

.station:hover h3 {
  color: var(--pillar);
}

.landing-page .station p:not(.station-cmd) {
  margin: 0;
  font-size: 0.97rem;
  line-height: 1.6;
  color: var(--vp-c-text-2);
}

.card-link {
  display: inline-block;
  margin-top: auto;
  padding-top: 20px;
  font-family: var(--vp-font-family-mono);
  font-size: 0.7rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--pillar, var(--vp-c-brand-1));
}

.card-link::after {
  content: "→";
  display: inline-block;
  margin-left: 6px;
  transition: transform 0.2s ease;
}

a:hover > .card-link::after,
a:hover > div + .card-link::after {
  transform: translateX(3px);
}

/* 03 · Day to day */
.landing-switch-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(360px, 1.1fr);
  gap: 56px;
  align-items: center;
}

.landing-page .landing-checklist {
  margin-top: 26px;
}

.landing-page .landing-checklist li {
  display: flex;
  gap: 14px;
  padding: 11px 0;
  border-top: 1px solid var(--vp-c-divider);
  font-size: 0.95rem;
  line-height: 1.5;
  color: var(--vp-c-text-1);
}

.landing-checklist li::before {
  content: "";
