    padding-bottom: 40px !important;
  }

  .VPHero .container {
    padding-right: 24px !important;
    padding-left: 24px !important;
  }

  .hero-copy h1 {
    font-size: 2.5rem;
  }

  .hero-lede {
    font-size: 1rem;
  }

  .hero-actions {
    flex-direction: column;
    align-items: stretch;
    width: 100%;
  }

  .hero-meta span + span::before {
    margin: 0 8px;
  }

  .landing-section,
  .landing-pantry,
  .landing-cta {
    margin-top: 64px;
  }

  .landing-page .landing-section h2 {
    font-size: 2.1rem;
  }

  .landing-ledger,
  .stations-grid {
    grid-template-columns: 1fr;
  }

  .ledger-before {
    border-right: 0;
    border-bottom: 1px solid var(--vp-c-divider);
  }

  .landing-pantry {
    padding: 36px 24px;
  }

  .landing-page .pantry-stat {
    font-size: 2.6rem;
  }

  .terminal-lines {
    font-size: 0.76rem;
  }

  .landing-cta {
    padding: 64px 24px 72px;
  }
}
