    ['legacy success', 'reject', true],
    ['both fail', 'reject', false],
    ['legacy throws', 'reject', 'throw'],
    ['Clipboard API missing', 'missing', false],
  ]) {
    let selected = null;
    const temporaries = new Set();
    const timers = new Map();
    let timerId = 0;
    const document = {
      body: { appendChild: (node) => temporaries.add(node) },
      createElement: () => ({ value: '', style: {}, setAttribute() {}, select() { selected = this; }, remove() { temporaries.delete(this); if (selected === this) selected = null; } }),
      createRange: () => ({ node: null, selectNodeContents(node) { this.node = node; } }),
      execCommand: () => { if (legacy === 'throw') throw Error('blocked'); return legacy; },
